SELECT condition_id, COUNT(*) AS row_count,
 MIN(ingest_ts) AS first_ingest, MAX(ingest_ts) AS last_ingest,
 COUNT(DISTINCT source_run_id) AS run_count,
 COUNT(DISTINCT question) AS question_versions,
 COUNT(DISTINCT outcomes::text) AS outcome_versions,
 COUNT(DISTINCT (active, closed, archived, enable_order_book)) AS status_states
FROM prediction_markets.polymarket_markets
WHERE condition_id IN ('0x0c4cd2055d6ea89354ffddc55d6dbcef9355748112ea952fc925f3db6a5c457f','0x38903ef70b7d9ee41ea22ef2aec6287e4e6c77ec8702ca741e37d5c5df090a4d','0x3910cb53f972d00c049ad674c1b183b375bd56786eb4c085ea217f84defdd1ca','0x58078283e2356f9b9537b42e7479d7785b83bcd6f18002de8a2526c499eda837','0x5ccfe1b69a582d2985db08a8481a0d74c314b1fce9b4711ae2efb2c6467fe6aa','0x75a50ed92507226816900d6da63984b4db752ad3a3f73e691514416cc5ccd980','0x84edef36bded182da6a395ac6c785dba8f3e09b6c5ad041385b2042536cbef25','0xa0f4c4924ea1a8b410b4ce821c2a9955fad21a1b19bdcfde90816732278b3dd5','0xbb57ccf5853a85487bc3d83d04d669310d28c6c810758953b9d9b91d1aee89d2','0xbe20fcfd54937c2a48a7b8521ca349e6a2c4373566328ebb950a8c35ab1be3d9','0xc9c9790c8f26dd9c8cabae9dd76be37aa86a6ded7de660e1da9d19324cf618d4','0xce6f2c7437b15b808a6be3ea61fc125077e35ce7cc55b66fdbf15f7ce22493ea','0xdaa4866bae18be58c5a79d2aeeffd035ec78f1bb49dbd88f72993997778a990f','0xe284a52d608552290b056def0a62e1914b3ebe316407504f56f6361fafc68358')
GROUP BY condition_id ORDER BY condition_id LIMIT 14
